import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

_SRC = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>

// Fixed geometry specialization: C=256, G=32, CPG=8, C4=64
#define FIX_C 256
#define FIX_G 32
#define FIX_CPG 8
#define FIX_C4 64
#define TPX 128

__device__ __forceinline__ float silu_f(float v) {
    return v / (1.0f + __expf(-v));
}

// ---------------------------------------------------------------- statistics
// x: NHWC contiguous. one block handles (n,g) pixel-segment s. CPG fixed to 8 (cpg4=2)
__global__ void gn_stats_kernel(const float* __restrict__ x,
                                float* __restrict__ partial,   // [2, BG, S]
                                int HW, int G, int S, int BG) {
    const int s  = blockIdx.x;
    const int bg = blockIdx.y;
    const int n  = bg / G;
    const int g  = bg - n * G;

    const long long base = (long long)n * HW * (long long)FIX_C + (long long)g * FIX_CPG;
    const int p_start = (int)(((long long)HW * s) / S);
    const int p_end   = (int)(((long long)HW * (s + 1)) / S);

    float sum = 0.f, sq = 0.f;
    const int cnt = (p_end - p_start) << 1;   // cpg4 = 2
    #pragma unroll 4
    for (int i = threadIdx.x; i < cnt; i += 256) {
        int p = p_start + (i >> 1);
        int j = i & 1;
        const float4 v = *reinterpret_cast<const float4*>(x + base + (long long)p * FIX_C + (j << 2));
        sum += v.x + v.y + v.z + v.w;
        sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }

    // block reduce
    __shared__ float ws[2][32];
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        sum += __shfl_down_sync(mask, sum, off);
        sq  += __shfl_down_sync(mask, sq,  off);
    }
    int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    if (lane == 0) { ws[0][warp] = sum; ws[1][warp] = sq; }
    __syncthreads();
    int nw = blockDim.x >> 5;
    if (warp == 0) {
        sum = (lane < nw) ? ws[0][lane] : 0.f;
        sq  = (lane < nw) ? ws[1][lane] : 0.f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            sum += __shfl_down_sync(mask, sum, off);
            sq  += __shfl_down_sync(mask, sq,  off);
        }
        if (lane == 0) {
            partial[(long long)bg * S + s]                 = sum;
            partial[(long long)BG * S + (long long)bg * S + s] = sq;
        }
    }
}

__global__ void gn_finalize_kernel(const float* __restrict__ partial,
                                   float* __restrict__ mean,
                                   float* __restrict__ rstd,
                                   int S, int BG, float inv_count, float eps) {
    const int bg = blockIdx.x;
    float sum = 0.f, sq = 0.f;
    for (int i = threadIdx.x; i < S; i += blockDim.x) {
        sum += partial[(long long)bg * S + i];
        sq  += partial[(long long)BG * S + (long long)bg * S + i];
    }
    __shared__ float ws[2][32];
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        sum += __shfl_down_sync(mask, sum, off);
        sq  += __shfl_down_sync(mask, sq,  off);
    }
    int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    if (lane == 0) { ws[0][warp] = sum; ws[1][warp] = sq; }
    __syncthreads();
    int nw = blockDim.x >> 5;
    if (warp == 0) {
        sum = (lane < nw) ? ws[0][lane] : 0.f;
        sq  = (lane < nw) ? ws[1][lane] : 0.f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            sum += __shfl_down_sync(mask, sum, off);
            sq  += __shfl_down_sync(mask, sq,  off);
        }
        if (lane == 0) {
            float m = sum * inv_count;
            float v = sq * inv_count - m * m;
            v = v < 0.f ? 0.f : v;
            mean[bg] = m;
            rstd[bg] = rsqrtf(v + eps);
        }
    }
}

// ------------------------------------------- GN(affine) + SiLU, NHWC -> NHWC
// specialized: C4=64, CPG=8 (c0 >> 3 gives group)
__global__ void gn_silu_nhwc_kernel(const float* __restrict__ x,
                                    const float* __restrict__ gamma,
                                    const float* __restrict__ beta,
                                    const float* __restrict__ mean,
                                    const float* __restrict__ rstd,
                                    float* __restrict__ y,
                                    int HWC4, int G) {
    const int n = blockIdx.y;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= HWC4) return;
    const int c0 = (idx & (FIX_C4 - 1)) << 2;
    const int g  = c0 >> 3;   // c0 / CPG, CPG=8
    const int bg = n * G + g;
    const float mu = mean[bg], rs = rstd[bg];

    const long long off = (long long)n * HWC4 + idx;
    const float4 v  = *reinterpret_cast<const float4*>(x + (off << 2));
    const float4 gm = *reinterpret_cast<const float4*>(gamma + c0);
    const float4 bt = *reinterpret_cast<const float4*>(beta + c0);
    float4 o;
    o.x = silu_f((v.x - mu) * rs * gm.x + bt.x);
    o.y = silu_f((v.y - mu) * rs * gm.y + bt.y);
    o.z = silu_f((v.z - mu) * rs * gm.z + bt.z);
    o.w = silu_f((v.w - mu) * rs * gm.w + bt.w);
    *reinterpret_cast<float4*>(y + (off << 2)) = o;
}

// ---------------- GN(affine) + SiLU + residual add, NHWC in -> NCHW out
// Specialized for CPG=8, TPX=128, blockDim=256.
// Shared array sm[TPX*9] laid out as sm[p*9 + c] (row stride 9 -> bank-conflict free)
__global__ void gn_silu_res_nchw_kernel(const float* __restrict__ x,
                                        const float* __restrict__ res,
                                        const float* __restrict__ gamma,
                                        const float* __restrict__ beta,
                                        const float* __restrict__ mean,
                                        const float* __restrict__ rstd,
                                        float* __restrict__ out,
                                        int HW, int G) {
    __shared__ float sm[TPX * 9];
    const int bg = blockIdx.y;
    const int n  = bg / G;
    const int g  = bg - n * G;
    const int p0 = blockIdx.x * TPX;
    const float mu = mean[bg], rs = rstd[bg];

    const long long base = (long long)n * HW * (long long)FIX_C + (long long)g * FIX_CPG;

    // Load phase: 256 threads, each thread handles a float4 (4 channels) for one pixel-half
    int t = threadIdx.x;
    int p = t >> 1;
    int j = t & 1;
    int pg = p0 + p;
    if (pg < HW) {
        float4 v = *reinterpret_cast<const float4*>(x + base + (long long)pg * FIX_C + (j << 2));
        float4 gm = *reinterpret_cast<const float4*>(gamma + (g << 3) + (j << 2));
        float4 bt = *reinterpret_cast<const float4*>(beta + (g << 3) + (j << 2));
        float r0 = silu_f((v.x - mu) * rs * gm.x + bt.x);
        float r1 = silu_f((v.y - mu) * rs * gm.y + bt.y);
        float r2 = silu_f((v.z - mu) * rs * gm.z + bt.z);
        float r3 = silu_f((v.w - mu) * rs * gm.w + bt.w);
        int base_idx = p * 9 + (j << 2);
        sm[base_idx + 0] = r0;
        sm[base_idx + 1] = r1;
        sm[base_idx + 2] = r2;
        sm[base_idx + 3] = r3;
    }
    __syncthreads();

    const long long obase = (long long)n * FIX_C * (long long)HW + (long long)g * FIX_CPG * HW;
    #pragma unroll
    for (int k = 0; k < 4; ++k) {
        int lin = (k << 8) + t;
        int c = lin >> 7;
        int pl = lin & 127;
        int pgo = p0 + pl;
        if (pgo < HW) {
            long long oi = obase + (long long)c * HW + pgo;
            out[oi] = sm[pl * 9 + c] + res[oi];
        }
    }
}

// ---------------------------------------------------------- weight transpose
// src: [O, C, KH, KW] contiguous (NCHW-style OIHW). dst: [O, KH, KW, C] (NHWC-style OHWI),
// which is exactly what channels_last memory format means for a 4D weight tensor.
// One block per output filter O. Shared mem holds C*KK floats.
__global__ void weight_nchw_to_nhwc_kernel(const float* __restrict__ src,
                                           float* __restrict__ dst,
                                           int C, int KK) {
    extern __shared__ float sm[];
    const long long base = (long long)blockIdx.x * (long long)C * KK;
    const int N9 = C * KK;
    // Coalesced read: consecutive threads read consecutive addresses of src
    // (src is laid out as [C, KK] for this filter -> i = c*KK + rs)
    for (int i = threadIdx.x; i < N9; i += blockDim.x) {
        float v = src[base + i];
        int c  = (KK == 9) ? (i / 9) : (i / KK);
        int rs = i - c * KK;
        sm[rs * C + c] = v;
    }
    __syncthreads();
    // Coalesced write: dst is laid out as [KK, C] for this filter -> i already matches
    for (int i = threadIdx.x; i < N9; i += blockDim.x) {
        dst[base + i] = sm[i];
    }
}

// ------------------------------------------------------------- x transpose
// src: [N, C, HW] contiguous NCHW (H*W flattened). dst: [N, HW, C] NHWC.
// 32x32 tiled shared-memory transpose, padded to avoid bank conflicts.
__global__ void nchw_to_nhwc_kernel(const float* __restrict__ src,
                                    float* __restrict__ dst,
                                    int C, int HW) {
    __shared__ float t[32][33];
    const int p0 = blockIdx.x * 32;
    const int c0 = blockIdx.y * 32;
    const int n  = blockIdx.z;

    #pragma unroll
    for (int i = 0; i < 32; i += 8) {
        int c = c0 + threadIdx.y + i;
        int p = p0 + threadIdx.x;
        if (p < HW) {
            t[threadIdx.y + i][threadIdx.x] = src[((long long)n * C + c) * HW + p];
        }
    }
    __syncthreads();

    #pragma unroll
    for (int i = 0; i < 32; i += 8) {
        int p = p0 + threadIdx.y + i;
        if (p < HW) {
            dst[((long long)n * HW + p) * C + c0 + threadIdx.x] = t[threadIdx.x][threadIdx.y + i];
        }
    }
}

// ------------------------------------------------------------------- launchers
static void compute_stats(const at::Tensor& x, int B, int HW, int G,
                          float eps, at::Tensor& mean, at::Tensor& rstd) {
    const int BG = B * G;
    int S = (456 + BG - 1) / BG;
    int maxS = (HW + 255) / 256;
    if (S > maxS) S = maxS;
    if (S < 1) S = 1;
    auto opts = x.options();
    auto partial = at::empty({2, BG, S}, opts);
    auto stream = at::cuda::getCurrentCUDAStream();

    dim3 grid(S, BG);
    gn_stats_kernel<<<grid, 256, 0, stream>>>(
        x.data_ptr<float>(), partial.data_ptr<float>(), HW, G, S, BG);
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    float inv_count = 1.0f / (float)((long long)HW * FIX_CPG);
    gn_finalize_kernel<<<BG, 256, 0, stream>>>(
        partial.data_ptr<float>(), mean.data_ptr<float>(), rstd.data_ptr<float>(),
        S, BG, inv_count, eps);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

torch::Tensor gn_silu_nhwc(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta,
                           int64_t B, int64_t HW, int64_t C, int64_t G, double eps) {
    TORCH_CHECK(x.scalar_type() == at::kFloat, "float32 only");
    TORCH_CHECK(C == FIX_C && G == FIX_G, "specialized kernel requires C=256,G=32");
    auto opts = x.options();
    auto mean = at::empty({B * G}, opts);
    auto rstd = at::empty({B * G}, opts);
    compute_stats(x, (int)B, (int)HW, (int)G, (float)eps, mean, rstd);

    auto y = at::empty_like(x);
    const int HWC4 = (int)HW * FIX_C4;
    auto stream = at::cuda::getCurrentCUDAStream();
    dim3 grid((HWC4 + 255) / 256, (unsigned)B);
    gn_silu_nhwc_kernel<<<grid, 256, 0, stream>>>(
        x.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        mean.data_ptr<float>(), rstd.data_ptr<float>(), y.data_ptr<float>(),
        HWC4, (int)G);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}

torch::Tensor gn_silu_res_nchw(torch::Tensor x, torch::Tensor res,
                               torch::Tensor gamma, torch::Tensor beta,
                               int64_t B, int64_t HW, int64_t C, int64_t G, double eps) {
    TORCH_CHECK(x.scalar_type() == at::kFloat, "float32 only");
    TORCH_CHECK(C == FIX_C && G == FIX_G, "specialized kernel requires C=256,G=32");
    auto opts = x.options();
    auto mean = at::empty({B * G}, opts);
    auto rstd = at::empty({B * G}, opts);
    compute_stats(x, (int)B, (int)HW, (int)G, (float)eps, mean, rstd);

    auto out = at::empty({B * C * HW}, opts);
    auto stream = at::cuda::getCurrentCUDAStream();
    dim3 grid(((int)HW + TPX - 1) / TPX, (unsigned)(B * G));
    size_t shm = sizeof(float) * TPX * 9;
    gn_silu_res_nchw_kernel<<<grid, 256, shm, stream>>>(
        x.data_ptr<float>(), res.data_ptr<float>(), gamma.data_ptr<float>(),
        beta.data_ptr<float>(), mean.data_ptr<float>(), rstd.data_ptr<float>(),
        out.data_ptr<float>(), (int)HW, (int)G);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}

torch::Tensor weight_to_nhwc(torch::Tensor w) {
    TORCH_CHECK(w.dim() == 4, "weight must be 4D");
    TORCH_CHECK(w.scalar_type() == at::kFloat, "float32 only");
    TORCH_CHECK(w.is_contiguous(), "weight must be NCHW-contiguous");
    const int O  = (int)w.size(0);
    const int C  = (int)w.size(1);
    const int KH = (int)w.size(2);
    const int KW = (int)w.size(3);
    const int KK = KH * KW;
    const size_t shm = (size_t)C * KK * sizeof(float);
    if (shm > 48 * 1024) {
        return w.contiguous(at::MemoryFormat::ChannelsLast);
    }
    auto dst = at::empty({O, C, KH, KW}, w.options().memory_format(at::MemoryFormat::ChannelsLast));
    auto stream = at::cuda::getCurrentCUDAStream();
    weight_nchw_to_nhwc_kernel<<<O, 256, shm, stream>>>(
        w.data_ptr<float>(), dst.data_ptr<float>(), C, KK);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return dst;
}

torch::Tensor x_to_nhwc(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 4, "x must be 4D");
    if (x.scalar_type() != at::kFloat || !x.is_contiguous() || (x.size(1) % 32 != 0)) {
        return x.contiguous(at::MemoryFormat::ChannelsLast);
    }
    const int N = (int)x.size(0);
    const int C = (int)x.size(1);
    const int H = (int)x.size(2);
    const int W = (int)x.size(3);
    const int HW = H * W;
    auto dst = at::empty_like(x, x.options().memory_format(at::MemoryFormat::ChannelsLast));
    auto stream = at::cuda::getCurrentCUDAStream();
    dim3 block(32, 8);
    dim3 grid((HW + 31) / 32, C / 32, N);
    nchw_to_nhwc_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(), dst.data_ptr<float>(), C, HW);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return dst;
}
"""

_CPP = r"""
torch::Tensor gn_silu_nhwc(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta,
                           int64_t B, int64_t HW, int64_t C, int64_t G, double eps);
torch::Tensor gn_silu_res_nchw(torch::Tensor x, torch::Tensor res,
                               torch::Tensor gamma, torch::Tensor beta,
                               int64_t B, int64_t HW, int64_t C, int64_t G, double eps);
torch::Tensor weight_to_nhwc(torch::Tensor w);
torch::Tensor x_to_nhwc(torch::Tensor x);
"""

_ext = load_inline(
    name="vae_res_block_fused_v3",
    cpp_sources=_CPP,
    cuda_sources=_SRC,
    functions=["gn_silu_nhwc", "gn_silu_res_nchw", "weight_to_nhwc", "x_to_nhwc"],
    verbose=False,
    extra_cflags=["-O3", "-std=c++20"],
    extra_cuda_cflags=[
        "-O3",
        "-std=c++20",
        "--expt-relaxed-constexpr",
        "-lineinfo",
        "-use_fast_math",
        "-gencode=arch=compute_90,code=sm_90",
    ],
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x, conv1_weight, norm1_weight, norm1_bias,
                conv2_weight, norm2_weight, norm2_bias, eps):
        G = 32
        B, C, H, W = x.shape
        HW = H * W

        if x.dtype != torch.float32 or C != 256 or C % (4 * G) != 0:
            # generic fallback (keeps semantics for unsupported configs)
            out = F.conv2d(x, conv1_weight, None, 1, 1)
            out = F.group_norm(out, G, norm1_weight, norm1_bias, eps)
            out = F.silu(out)
            out = F.conv2d(out, conv2_weight, None, 1, 1)
            out = F.group_norm(out, G, norm2_weight, norm2_bias, eps)
            out = F.silu(out)
            return out + x

        xl = x.contiguous() if not x.is_contiguous() else x
        xl = _ext.x_to_nhwc(xl)
        w1 = _ext.weight_to_nhwc(conv1_weight) if conv1_weight.is_contiguous() else conv1_weight.contiguous(memory_format=torch.channels_last)
        w2 = _ext.weight_to_nhwc(conv2_weight) if conv2_weight.is_contiguous() else conv2_weight.contiguous(memory_format=torch.channels_last)
        g1 = norm1_weight if norm1_weight.is_contiguous() else norm1_weight.contiguous()
        b1 = norm1_bias if norm1_bias.is_contiguous() else norm1_bias.contiguous()
        g2 = norm2_weight if norm2_weight.is_contiguous() else norm2_weight.contiguous()
        b2 = norm2_bias if norm2_bias.is_contiguous() else norm2_bias.contiguous()

        y = F.conv2d(xl, w1, None, 1, 1)                       # cuDNN NHWC (vendor)
        y = _ext.gn_silu_nhwc(y, g1, b1, B, HW, C, G, float(eps))
        y = F.conv2d(y, w2, None, 1, 1)                        # cuDNN NHWC (vendor)
        xc = x if x.is_contiguous() else x.contiguous()
        out = _ext.gn_silu_res_nchw(y, xc, g2, b2, B, HW, C, G, float(eps))
        return out.view(B, C, H, W)
